      other.city == city &&
      other.district == district &&
      other.spaceType == spaceType &&
      other.feeNote == feeNote &&
      other.note == note &&
      other.scooterTotal == scooterTotal &&
      other.available == available &&
      other.scooterAllowed == scooterAllowed &&
      other.heavyAllowed == heavyAllowed &&
      other.scooterNotStated == scooterNotStated &&
      other.heavyNotStated == heavyNotStated &&
      other.status == status &&
      other.updatedAt == updatedAt &&
      other.lastConfirmedAt == lastConfirmedAt &&
      other.createdAt == createdAt &&
      other.scooterVerifiedAt == scooterVerifiedAt &&
      other.heavyVerifiedAt == heavyVerifiedAt &&
      other.facilityType == facilityType &&
      _equal(other.facilityTypes, facilityTypes) &&
      other.parkingAccess == parkingAccess &&
      other.address == address &&
      other.roadSegment == roadSegment &&
      other.entranceNote == entranceNote &&
      other.parkingGuide == parkingGuide &&
      other.specialRules == specialRules &&
      _equal(other.photoUrls, photoUrls) &&
      _equal(other.parkingZones, parkingZones) &&
      _equal(other.fee, fee) &&
      _equal(other.condition, condition) &&
      _equal(other.parkingSegments, parkingSegments) &&
      other.zonesComplete == zonesComplete &&
      _equal(other.closure, closure) &&
      other.closureState == closureState &&
      other.contributorName == contributorName &&
      other.contributorRole == contributorRole &&
      other.contributorHandle == contributorHandle &&
      other.isOwn == isOwn;

  @override
  int get hashCode => Object.hashAll([
    id,
    source,
    sourceName,
    sourceUrl,
    licenseNote,
    name,
    lat,
    lng,
    city,
    district,
    spaceType,
    feeNote,
    note,
    scooterTotal,
    available,
    scooterAllowed,
    heavyAllowed,
    scooterNotStated,
    heavyNotStated,
    status,
    updatedAt,
    lastConfirmedAt,
    createdAt,
    scooterVerifiedAt,
    heavyVerifiedAt,
    facilityType,
    _hash(facilityTypes),
    parkingAccess,
    address,
    roadSegment,
    entranceNote,
    parkingGuide,
    specialRules,
    _hash(photoUrls),
    _hash(parkingZones),
    _hash(fee),
    _hash(condition),
    _hash(parkingSegments),
    zonesComplete,
    _hash(closure),
    closureState,
    contributorName,
    contributorRole,
    contributorHandle,
    isOwn,
  ]);
}

/// 資料集名稱 → 版本號（正整數）。目前有 rules、spots；新增的資料集會出現新的鍵，用戶端遇到不認識的鍵請略過
class DataVersions {
  const DataVersions({required this.rules, required this.spots});

  factory DataVersions.fromJson(Map<String, Object?> json) => DataVersions(
    rules: (json['rules'] as num).toInt(),
    spots: (json['spots'] as num).toInt(),
  );

  final int rules;

  final int spots;

  Map<String, Object?> toJson() => {'rules': rules, 'spots': spots};

  @override
  bool operator ==(Object other) =>
      other is DataVersions && other.rules == rules && other.spots == spots;

  @override
  int get hashCode => Object.hashAll([rules, spots]);
}

/// 帳號刪除申請的狀態（#215）
class AccountDeletionState {
  const AccountDeletionState({
    required this.status,
    this.requestedAt,
    this.scheduledAt,
    required this.canSelfDelete,
    this.cannotSelfDeleteReason,
  });

  factory AccountDeletionState.fromJson(Map<String, Object?> json) =>
      AccountDeletionState(
        status: json['status'] as String,
        requestedAt: json['requested_at'] == null
            ? null
            : json['requested_at'] as String,
        scheduledAt: json['scheduled_at'] == null
            ? null
            : json['scheduled_at'] as String,
        canSelfDelete: json['can_self_delete'] as bool,
        cannotSelfDeleteReason: json['cannot_self_delete_reason'] == null
            ? null
            : json['cannot_self_delete_reason'] as String,
      );

  /// none：沒有申請；pending：冷靜期中，到 scheduled_at 後刪除
  final String status;

  /// ISO 8601 時間。申請時間；none 時為 null
  final String? requestedAt;

  /// ISO 8601 時間。最早刪除時間（申請＋7 天），實際在之後的每日排程（台灣 03:41）執行；none 時為 null
  final String? scheduledAt;

  /// 這個帳號能不能自助申請刪除；管理員為 false（要先由其他管理員移除權限）。App 在刪除說明頁就依此提示
  final bool canSelfDelete;

  /// 不能自助刪除的原因（錯誤碼）；可以時為 null
  final String? cannotSelfDeleteReason;

  Map<String, Object?> toJson() => {
    'status': status,
    'requested_at': requestedAt,
    'scheduled_at': scheduledAt,
    'can_self_delete': canSelfDelete,
    'cannot_self_delete_reason': cannotSelfDeleteReason,
  };

  @override
  bool operator ==(Object other) =>
      other is AccountDeletionState &&
      other.status == status &&
      other.requestedAt == requestedAt &&
      other.scheduledAt == scheduledAt &&
      other.canSelfDelete == canSelfDelete &&
      other.cannotSelfDeleteReason == cannotSelfDeleteReason;

  @override
  int get hashCode => Object.hashAll([
    status,
    requestedAt,
    scheduledAt,
    canSelfDelete,
    cannotSelfDeleteReason,
  ]);
}

class SpotsByIds {
