/// 自己隱藏的車友（#280）
class HiddenRiders {
  const HiddenRiders({required this.items, required this.limit});

  factory HiddenRiders.fromJson(Map<String, Object?> json) => HiddenRiders(
    items: [
      for (final e in json['items'] as List)
        HiddenRider.fromJson(e as Map<String, Object?>),
    ],
    limit: (json['limit'] as num).toInt(),
  );

  /// 依 hidden_at 新到舊
  final List<HiddenRider> items;

  /// 每帳號上限（500）
  final int limit;

  Map<String, Object?> toJson() => {
    'items': [for (final e in items) e.toJson()],
    'limit': limit,
  };

  @override
  bool operator ==(Object other) =>
      other is HiddenRiders &&
      _equal(other.items, items) &&
      other.limit == limit;

  @override
  int get hashCode => Object.hashAll([_hash(items), limit]);
}

bool _equal(Object? a, Object? b) {
  if (a is List && b is List) {
    if (a.length != b.length) return false;
    for (var i = 0; i < a.length; i++) {
      if (!_equal(a[i], b[i])) return false;
    }
    return true;
  }
  if (a is Map && b is Map) {
    if (a.length != b.length) return false;
    for (final key in a.keys) {
      if (!b.containsKey(key) || !_equal(a[key], b[key])) return false;
    }
    return true;
  }
  return a == b;
}

int _hash(Object? value) => switch (value) {
  List() => Object.hashAll(value.map(_hash)),
  Map() => Object.hashAllUnordered(
    value.entries.map((e) => Object.hash(e.key, _hash(e.value))),
  ),
  _ => value.hashCode,
};
